function beforeSwap(address sender, IPoolManager.PoolKey calldata, IPoolManager.SwapParams calldata)
    external
    override
    returns (bytes4)
{
    State s = state();
    if (s == State.OPEN) {
        _ringOpeningBell(sender);
    } else if (s == State.HOLIDAY) {
        revert ClosedForHoliday(getHoliday());
    } else if (s == State.WEEKEND) {
        revert ClosedForWeekend();
    } else if (s == State.AFTER_HOURS) {
        revert AfterHours();
    }
    return BaseHook.beforeSwap.selector;
}

